11	// Author: Tan, Zhiyuan
12	// Description: Sharemem main module
13	`timescale 1ns/1ns
14	
15	`include "define.v"
16	
17	module shared_mem (
18	  input                                                 clk                    ,
19	  input                                                 rst_n                  ,
20	  input                                                 core_req_valid_i       ,
21	  output                                                core_req_ready_o       ,
22	  input  [`WIDBITS-1:0]                                 core_req_instrid_i     ,
23	  input                                                 core_req_iswrite_i     ,
24	  input  [`DCACHE_TAGBITS-1:0]                          core_req_tag_i         ,
25	  input  [`DCACHE_SETIDXBITS-1:0]                       core_req_setidx_i      ,
26	  input  [`SHAREMEM_NLANES-1:0]                         core_req_activemask_i  ,
27	  input  [`SHAREMEM_NLANES*`DCACHE_BLOCKOFFSETBITS-1:0] core_req_blockoffset_i ,
28	  input  [`SHAREMEM_NLANES*`BYTESOFWORD-1:0]            core_req_wordoffset1h_i,
29	  input  [`SHAREMEM_NLANES*`XLEN-1:0]                   core_req_data_i        ,
30	  output                                                core_rsp_valid_o       ,
31	  input                                                 core_rsp_ready_i       ,
32	  output                                                core_rsp_iswrite_o     ,
33	  output [`WIDBITS-1:0]                                 core_rsp_instrid_o     ,
34	  output [`SHAREMEM_NLANES*`XLEN-1:0]                   core_rsp_data_o        ,
35	  output [`SHAREMEM_NLANES-1:0]                         core_rsp_activemask_o  
36	);
37	
38	  localparam SRAM_SET   = `SHAREDMEM_DEPTH*`SHAREDMEM_NWAYS*`SHAREDMEM_BLOCKWORDS/`SHAREMEM_NBANKS;
39	  localparam SETIDXBITS = $clog2(SRAM_SET);//`DCACHE_SETIDXBITS+`SHAREDMEM_BLOCKOFFSETBITS-`SHAREMEM_BANKIDXBITS     ;
40	  localparam BANKOFFSET_ISZERO = `DCACHE_BLOCKOFFSETBITS <= `SHAREMEM_BANKIDXBITS;
41	  localparam RSP_FIFO_DEPTH    = 4;
42	  localparam RSP_FIFO_CNT_DEPTH= 3;
43	
44	  //corereq_st0: input reg
45	  reg                                                core_req_fire_st0        ;
46	  reg [`WIDBITS-1:0]                                 core_req_instrid_st0     ;
47	  reg                                                core_req_iswrite_st0     ;
48	  reg [`DCACHE_TAGBITS-1:0]                          core_req_tag_st0         ;
49	  reg [`DCACHE_SETIDXBITS-1:0]                       core_req_setidx_st0      ;
50	  reg [`SHAREMEM_NLANES-1:0]                         core_req_activemask_st0  ;
51	  reg [`DCACHE_BLOCKOFFSETBITS*`SHAREMEM_NLANES-1:0] core_req_blockoffset_st0 ;
52	  reg [`BYTESOFWORD*`SHAREMEM_NLANES-1:0]            core_req_wordoffset1h_st0;
53	  reg [`XLEN*`SHAREMEM_NLANES-1:0]                   core_req_data_st0        ;
54	
55	  always@(posedge clk or negedge rst_n) begin
56	    if(!rst_n) begin
57	      core_req_fire_st0 <= 'd0;
58	    end
59	    else begin
60	      core_req_fire_st0 <= core_req_valid_i && core_req_ready_o;
61	    end
62	  end
63	
64	  always@(posedge clk or negedge rst_n) begin
65	    if(!rst_n) begin
66	      core_req_instrid_st0      <= 'd0;
67	      core_req_iswrite_st0      <= 'd0;
68	      core_req_tag_st0          <= 'd0;
69	      core_req_setidx_st0       <= 'd0;
70	      core_req_activemask_st0   <= 'd0;
71	      core_req_blockoffset_st0  <= 'd0;
72	      core_req_wordoffset1h_st0 <= 'd0;
73	      core_req_data_st0         <= 'd0;
74	    end
75	    else begin
76	      if(core_req_valid_i && core_req_ready_o) begin
77	        core_req_instrid_st0      <= core_req_instrid_i     ;
78	        core_req_iswrite_st0      <= core_req_iswrite_i     ;
79	        core_req_tag_st0          <= core_req_tag_i         ;
80	        core_req_setidx_st0       <= core_req_setidx_i      ;
81	        core_req_activemask_st0   <= core_req_activemask_i  ;
82	        core_req_blockoffset_st0  <= core_req_blockoffset_i ;
83	        core_req_wordoffset1h_st0 <= core_req_wordoffset1h_i;
84	        core_req_data_st0         <= core_req_data_i        ;
85	      end
86	      else begin
87	        core_req_instrid_st0      <= core_req_instrid_st0     ;
88	        core_req_iswrite_st0      <= core_req_iswrite_st0     ;
89	        core_req_tag_st0          <= core_req_tag_st0         ;
90	        core_req_setidx_st0       <= core_req_setidx_st0      ;
91	        core_req_activemask_st0   <= core_req_activemask_st0  ;
92	        core_req_blockoffset_st0  <= core_req_blockoffset_st0 ;
93	        core_req_wordoffset1h_st0 <= core_req_wordoffset1h_st0;
94	        core_req_data_st0         <= core_req_data_st0        ;
95	      end
96	    end
97	  end
98	
99	  //corereq_st1
100	  reg [`WIDBITS-1:0]                                 core_req_instrid_st1     ;
101	  reg                                                core_req_iswrite_st1     ;
102	  reg [`DCACHE_TAGBITS-1:0]                          core_req_tag_st1         ;
103	  reg [`DCACHE_SETIDXBITS-1:0]                       core_req_setidx_st1      ;
104	  reg [`SHAREMEM_NLANES-1:0]                         core_req_activemask_st1  ;
105	  reg [`DCACHE_BLOCKOFFSETBITS*`SHAREMEM_NLANES-1:0] core_req_blockoffset_st1 ;
106	  reg [`BYTESOFWORD*`SHAREMEM_NLANES-1:0]            core_req_wordoffset1h_st1;
107	  reg [`XLEN*`SHAREMEM_NLANES-1:0]                   core_req_data_st1        ;
108	
109	  wire [`XLEN-1:0] core_req_data_st1_wire [0:`SHAREMEM_NLANES-1];
110	
111	  always@(posedge clk or negedge rst_n) begin
112	    if(!rst_n) begin
113	      core_req_instrid_st1    <= 'd0;
114	      core_req_iswrite_st1    <= 'd0;
115	      core_req_tag_st1        <= 'd0;
116	      core_req_setidx_st1     <= 'd0;
117	      core_req_activemask_st1 <= 'd0;
118	    end
119	    else begin
120	      if(core_req_fire_st0) begin
121	        core_req_instrid_st1    <= core_req_instrid_st0   ;
122	        core_req_iswrite_st1    <= core_req_iswrite_st0   ;
123	        core_req_tag_st1        <= core_req_tag_st0       ;
124	        core_req_setidx_st1     <= core_req_setidx_st0    ;
125	        core_req_activemask_st1 <= core_req_activemask_st0;
126	      end
127	      else begin
128	        core_req_instrid_st1    <= core_req_instrid_st1   ;
129	        core_req_iswrite_st1    <= core_req_iswrite_st1   ;
130	        core_req_tag_st1        <= core_req_tag_st1       ;
131	        core_req_setidx_st1     <= core_req_setidx_st1    ;
132	        core_req_activemask_st1 <= core_req_activemask_st1;
133	      end
134	    end
135	  end
136	
137	  genvar i;
138	  generate for(i=0;i<`SHAREMEM_NLANES;i=i+1) begin: COREREQ
139	    always@(posedge clk or negedge rst_n) begin
140	      if(!rst_n) begin
141	        core_req_blockoffset_st1[`DCACHE_BLOCKOFFSETBITS*(i+1)-1:`DCACHE_BLOCKOFFSETBITS*i]  <= 'd0;
142	        core_req_wordoffset1h_st1[`BYTESOFWORD*(i+1)-1:`BYTESOFWORD*i]                       <= 'd0;
143	        core_req_data_st1[`XLEN*(i+1)-1:`XLEN*i]                                             <= 'd0;
144	      end
145	      else begin
146	        if(core_req_fire_st0) begin
147	          core_req_blockoffset_st1[`DCACHE_BLOCKOFFSETBITS*(i+1)-1:`DCACHE_BLOCKOFFSETBITS*i]  <= core_req_blockoffset_st0[`DCACHE_BLOCKOFFSETBITS*(i+1)-1:`DCACHE_BLOCKOFFSETBITS*i]; 
148	          core_req_wordoffset1h_st1[`BYTESOFWORD*(i+1)-1:`BYTESOFWORD*i] <= core_req_wordoffset1h_st0[`BYTESOFWORD*(i+1)-1:`BYTESOFWORD*i];
149	          core_req_data_st1[`XLEN*(i+1)-1:`XLEN*i] <= core_req_data_st0[`XLEN*(i+1)-1:`XLEN*i];
150	        end
151	        else begin
152	          core_req_blockoffset_st1[`DCACHE_BLOCKOFFSETBITS*(i+1)-1:`DCACHE_BLOCKOFFSETBITS*i]  <= core_req_blockoffset_st1[`DCACHE_BLOCKOFFSETBITS*(i+1)-1:`DCACHE_BLOCKOFFSETBITS*i] ;
153	          core_req_wordoffset1h_st1[`BYTESOFWORD*(i+1)-1:`BYTESOFWORD*i] <= core_req_wordoffset1h_st1[`BYTESOFWORD*(i+1)-1:`BYTESOFWORD*i];
154	          core_req_data_st1[`XLEN*(i+1)-1:`XLEN*i] <= core_req_data_st1[`XLEN*(i+1)-1:`XLEN*i];
155	        end
156	      end
157	    end
158	
159	    assign core_req_data_st1_wire[i] = core_req_data_st1[`XLEN*(i+1)-1:`XLEN*i];
160	  end
161	  endgenerate
162	
163	  wire                                                bankconf_core_req_arb_is_write       ;
164	  wire                                                bankconf_core_req_arb_enable         ;
165	  wire [`SHAREMEM_NLANES-1:0]                         bankconf_core_req_arb_activemask     ;
166	  wire [`SHAREMEM_NLANES*`DCACHE_BLOCKOFFSETBITS-1:0] bankconf_core_req_arb_blockoffset    ;
167	  wire [`SHAREMEM_NLANES*`BYTESOFWORD-1:0]            bankconf_core_req_arb_wordoffset1h   ;
168	  wire [`SHAREMEM_NLANES*`SHAREMEM_NBANKS-1:0]        bankconf_data_crsbar_write_sel1h     ;
169	  wire [`SHAREMEM_NBANKS*`SHAREMEM_NLANES-1:0]        bankconf_data_crsbar_read_sel1h      ;
170	  wire [`SHAREMEM_NBANKS*`SHAREMEM_BANKOFFSET-1:0]    bankconf_data_crsbar_out_bankoffset  ;
171	  wire [`SHAREMEM_NBANKS*`BYTESOFWORD-1:0]            bankconf_data_crsbar_out_wordoffset1h;
172	  wire [`SHAREMEM_NBANKS-1:0]                         bankconf_data_array_en               ;
173	  wire [`SHAREMEM_NLANES-1:0]                         bankconf_active_lane                 ;
174	  wire                                                bankconf_bankconflict                ;
175	  reg                                                 bankconflict_reg                     ;
176	
177	  assign bankconf_core_req_arb_is_write     = bankconflict_reg ? core_req_iswrite_st1 : core_req_iswrite_st0;
178	  assign bankconf_core_req_arb_enable       = core_req_fire_st0                                             ;
179	  assign bankconf_core_req_arb_activemask   = core_req_activemask_st0                                       ;
180	  assign bankconf_core_req_arb_blockoffset  = core_req_blockoffset_st0                                      ;
181	  assign bankconf_core_req_arb_wordoffset1h = core_req_wordoffset1h_st0                                     ;
182	
183	  bankconflict_arb bankconf (
184	    .clk                            (clk                                  ),
185	    .rst_n                          (rst_n                                ),
186	    .core_req_arb_is_write_i        (bankconf_core_req_arb_is_write       ),
187	    .core_req_arb_enable_i          (bankconf_core_req_arb_enable         ),
188	    .core_req_arb_activemask_i      (bankconf_core_req_arb_activemask     ),
189	    .core_req_arb_blockoffset_i     (bankconf_core_req_arb_blockoffset    ),
190	    .core_req_arb_wordoffset1h_i    (bankconf_core_req_arb_wordoffset1h   ),
191	    .data_crsbar_write_sel1h_o      (bankconf_data_crsbar_write_sel1h     ),
192	    .data_crsbar_read_sel1h_o       (bankconf_data_crsbar_read_sel1h      ),
193	    .data_crsbar_out_bankoffset_o   (bankconf_data_crsbar_out_bankoffset  ),
194	    .data_crsbar_out_wordoffset1h_o (bankconf_data_crsbar_out_wordoffset1h),
195	    .data_array_en_o                (bankconf_data_array_en               ),
196	    .active_lane_o                  (bankconf_active_lane                 ),
197	    .bankconflict_o                 (bankconf_bankconflict                )
198	  );
199	
200	  //pipeline regs
201	  reg                                             core_req_isvalid_write_st1               ;
202	  reg                                             core_req_isvalid_read_st1                ;
203	  reg                                             core_req_isvalid_write_st2               ;
204	  reg                                             core_req_isvalid_read_st2                ;
205	  reg                                             core_req_iswrite_st2                     ;
206	  reg [`WIDBITS-1:0]                              core_req_instrid_st2                     ;
207	  reg [`SHAREMEM_NLANES-1:0]                      bankconf_activelane_st1                  ;
208	  reg [`SHAREMEM_NLANES-1:0]                      bankconf_activelane_st2                  ;
209	  reg [`SHAREMEM_NBANKS-1:0]                      bankconf_data_array_en_st1               ;
210	  reg [`SHAREMEM_NLANES*`SHAREMEM_NBANKS-1:0]     data_crsbar_write_sel1h_st1              ;
211	  reg [`SHAREMEM_NBANKS*`SHAREMEM_NLANES-1:0]     data_crsbar_read_sel1h_st1               ;
212	  reg [`SHAREMEM_NBANKS*`SHAREMEM_NLANES-1:0]     data_crsbar_read_sel1h_st2               ; 
213	  reg [`SHAREMEM_NBANKS*`SHAREMEM_BANKOFFSET-1:0] bankconf_data_crsbar_out_bankoffset_st1  ;
214	  reg [`SHAREMEM_NBANKS*`BYTESOFWORD-1:0]         bankconf_data_crsbar_out_wordoffset1h_st1;
215	
216	  wire [`SHAREMEM_BANKIDXBITS-1:0]    crsbar_sel_for_read  [0:`SHAREMEM_NLANES-1];
217	  wire [$clog2(`SHAREMEM_NLANES)-1:0] crsbar_sel_for_write [0:`SHAREMEM_NBANKS-1];
218	
219	
220	  always@(posedge clk or negedge rst_n) begin
221	    if(!rst_n) begin
222	      bankconflict_reg            <= 'd0;
223	      core_req_isvalid_write_st1  <= 'd0;
224	      core_req_isvalid_read_st1   <= 'd0;
225	      core_req_isvalid_write_st2  <= 'd0;
226	      core_req_isvalid_read_st2   <= 'd0;
227	      core_req_iswrite_st2        <= 'd0;
228	      core_req_instrid_st2        <= 'd0;
229	      bankconf_activelane_st1     <= 'd0;
230	      bankconf_activelane_st2     <= 'd0;
231	      bankconf_data_array_en_st1  <= 'd0;
232	      bankconf_data_crsbar_out_bankoffset_st1   <= 'd0;
233	      bankconf_data_crsbar_out_wordoffset1h_st1 <= 'd0;
234	    end
235	    else begin
236	      bankconflict_reg            <= bankconf_bankconflict           ;
237	      core_req_isvalid_write_st2  <= core_req_isvalid_write_st1      ;
238	      core_req_isvalid_read_st2   <= core_req_isvalid_read_st1       ;
239	      core_req_iswrite_st2        <= core_req_iswrite_st1            ;
240	      core_req_instrid_st2        <= core_req_instrid_st1            ;
241	      bankconf_activelane_st1     <= bankconf_active_lane            ;
242	      bankconf_activelane_st2     <= bankconf_activelane_st1         ;
243	      bankconf_data_array_en_st1  <= bankconf_data_array_en          ;
244	      core_req_isvalid_write_st1  <= (core_req_fire_st0 && core_req_iswrite_st0) || (core_req_isvalid_write_st1 && bankconflict_reg);
245	      core_req_isvalid_read_st1   <= (core_req_fire_st0 && !core_req_iswrite_st0) || (core_req_isvalid_read_st1 && bankconflict_reg);
246	      bankconf_data_crsbar_out_bankoffset_st1   <= bankconf_data_crsbar_out_bankoffset  ;
247	      bankconf_data_crsbar_out_wordoffset1h_st1 <= bankconf_data_crsbar_out_wordoffset1h;
248	    end
249	  end
250	
251	  wire [`XLEN-1:0]                  data_for_write     [0:`SHAREMEM_NBANKS-1];
252	  wire [`XLEN-1:0]                  read_data          [0:`SHAREMEM_NBANKS-1];
253	  wire [`XLEN*-1:0]                 read_data_st2_wire [0:`SHAREMEM_NBANKS-1];
254	  reg  [SETIDXBITS-1:0]             write_setidx       [0:`SHAREMEM_NBANKS-1];
255	  reg  [SETIDXBITS-1:0]             read_setidx        [0:`SHAREMEM_NBANKS-1];
256	  reg  [`XLEN*`SHAREMEM_NBANKS-1:0] read_data_st2                            ;
257	
258	  wire read_data_valid;
259	  assign read_data_valid = (core_req_fire_st0 && !core_req_iswrite_st0) || (core_req_isvalid_read_st1 && bankconflict_reg);
260	
261	  wire [`BABITS-1:0]    core_req_ba_st0         ;
262	  wire [`BABITS-1:0]    core_req_ba_st1         ;
263	  wire [SETIDXBITS-1:0] core_req_setidx_bank_st0;
264	  wire [SETIDXBITS-1:0] core_req_setidx_bank_st1;
265	
266	  assign core_req_ba_st0          = {core_req_tag_st0,core_req_setidx_st0};
267	  assign core_req_ba_st1          = {core_req_tag_st1,core_req_setidx_st1};
268	  assign core_req_setidx_bank_st0 = core_req_ba_st0[SETIDXBITS-1:0]       ;
269	  assign core_req_setidx_bank_st1 = core_req_ba_st1[SETIDXBITS-1:0]       ;
270	
271	  genvar j;
272	  generate for(j=0;j<`SHAREMEM_NBANKS;j=j+1) begin: SRAM_IN
273	    assign data_for_write[j] = core_req_data_st1_wire[crsbar_sel_for_write[j]];
274	
275	    always@(posedge clk or negedge rst_n) begin
276	      if(!rst_n) begin
277	        data_crsbar_write_sel1h_st1[`SHAREMEM_NLANES*(j+1)-1:`SHAREMEM_NLANES*j] <= 'd0;
278	      end
279	      else begin
280	        data_crsbar_write_sel1h_st1[`SHAREMEM_NLANES*(j+1)-1:`SHAREMEM_NLANES*j] <= bankconf_data_crsbar_write_sel1h[`SHAREMEM_NLANES*(j+1)-1:`SHAREMEM_NLANES*j];
281	      end
282	    end
283	
284	    one2bin #(
285	      .ONE_WIDTH (`SHAREMEM_NLANES        ),
286	      .BIN_WIDTH ($clog2(`SHAREMEM_NLANES))
287	    )
288	    sel_write (
289	      .oh  (data_crsbar_write_sel1h_st1[`SHAREMEM_NLANES*(j+1)-1:`SHAREMEM_NLANES*j]),
290	      .bin (crsbar_sel_for_write[j]                                                 )
291	    );
292	    
293	    always@(*) begin
294	      if(BANKOFFSET_ISZERO) begin
295	        write_setidx[j] = core_req_setidx_bank_st1;
296	        read_setidx[j]  = core_req_setidx_bank_st0;
297	      end
298	      else begin
299	        write_setidx[j] = {core_req_setidx_bank_st1,bankconf_data_crsbar_out_bankoffset_st1[`SHAREMEM_BANKOFFSET*(j+1)-1:`SHAREMEM_BANKOFFSET*j]};
300	        read_setidx[j]  = {core_req_setidx_bank_st0,bankconf_data_crsbar_out_bankoffset[`SHAREMEM_BANKOFFSET*(j+1)-1:`SHAREMEM_BANKOFFSET*j]}      ;
301	      end
302	    end
303	
304	    sram_template #(
305	      .GEN_WIDTH (8           ),
306	      .NUM_SET   (SRAM_SET    ),
307	      .NUM_WAY   (`BYTESOFWORD),
308	      .SET_DEPTH (SETIDXBITS  )
309	    )
310	    data_access (
311	      .clk             (clk                                                                           ),
312	      .rst_n           (rst_n                                                                         ),
313	      .r_req_valid_i   (read_data_valid                                                               ),
314	      .r_req_setid_i   (read_setidx[j]                                                                ),
315	      .r_resp_data_o   (read_data[j]                                                                  ),
316	      .w_req_valid_i   (core_req_isvalid_write_st1 && bankconf_data_array_en_st1[j]                   ),
317	      .w_req_setid_i   (write_setidx[j]                                                               ),
318	      .w_req_waymask_i (bankconf_data_crsbar_out_wordoffset1h_st1[`BYTESOFWORD*(j+1)-1:`BYTESOFWORD*j]),
319	      .w_req_data_i    (data_for_write[j]                                                             )
320	    );
321	
322	    always@(posedge clk or negedge rst_n) begin
323	      if(!rst_n) begin
324	        read_data_st2[`XLEN*(j+1)-1:`XLEN*j] <= 'd0;
325	      end
326	      else begin
327	        read_data_st2[`XLEN*(j+1)-1:`XLEN*j] <= read_data[j];
328	      end
329	    end
330	
331	    assign read_data_st2_wire[j] = read_data_st2[`XLEN*(j+1)-1:`XLEN*j];
332	      
333	  end
334	  endgenerate
335	
336	  wire [`XLEN-1:0] data_crsbar_out [0:`SHAREMEM_NLANES-1];
337	
338	  genvar k;
339	  generate for(k=0;k<`SHAREMEM_NLANES;k=k+1) begin: SRAM_OUT
340	    always@(posedge clk or negedge rst_n) begin
341	      if(!rst_n) begin
342	        data_crsbar_read_sel1h_st1[`SHAREMEM_NBANKS*(k+1)-1:`SHAREMEM_NBANKS*k] <= 'd0;
343	        data_crsbar_read_sel1h_st2[`SHAREMEM_NBANKS*(k+1)-1:`SHAREMEM_NBANKS*k] <= 'd0;
344	      end
345	      else begin
346	        data_crsbar_read_sel1h_st1[`SHAREMEM_NBANKS*(k+1)-1:`SHAREMEM_NBANKS*k] <= bankconf_data_crsbar_read_sel1h[`SHAREMEM_NBANKS*(k+1)-1:`SHAREMEM_NBANKS*k];
347	        data_crsbar_read_sel1h_st2[`SHAREMEM_NBANKS*(k+1)-1:`SHAREMEM_NBANKS*k] <= data_crsbar_read_sel1h_st1[`SHAREMEM_NBANKS*(k+1)-1:`SHAREMEM_NBANKS*k]     ;
348	      end
349	    end
350	
351	    one2bin #(
352	      .ONE_WIDTH (`SHAREMEM_NBANKS     ),
353	      .BIN_WIDTH (`SHAREMEM_BANKIDXBITS)
354	    )
355	    sel_write (
356	      .oh  (data_crsbar_read_sel1h_st2[`SHAREMEM_NBANKS*(k+1)-1:`SHAREMEM_NBANKS*k]),
357	      .bin (crsbar_sel_for_read[k]                                                 )
358	    );
359	
360	    assign data_crsbar_out[k] = read_data_st2_wire[crsbar_sel_for_read[k]];
361	  end
362	  endgenerate
363	
364	  wire                                                      rsp_q_enq_valid;
365	  wire                                                      rsp_q_enq_ready;
366	  wire [`WIDBITS+`SHAREMEM_NLANES+`SHAREMEM_NLANES*`XLEN:0] rsp_q_enq_bits ;
367	  wire [`WIDBITS+`SHAREMEM_NLANES+`SHAREMEM_NLANES*`XLEN:0] rsp_q_deq_bits ;
368	  wire [RSP_FIFO_CNT_DEPTH-1:0]                             rsp_q_count    ;
369	  wire                                                      rsp_q_alm_full ;
370	
371	  genvar n;
372	  generate for(n=0;n<`SHAREMEM_NLANES;n=n+1) begin: RSP_DATA
373	    assign rsp_q_enq_bits[`XLEN*(n+1)-1:`XLEN*n] = data_crsbar_out[n];
374	  end
375	  endgenerate
376	
377	  assign rsp_q_enq_valid = core_req_isvalid_read_st2 || core_req_isvalid_write_st2;
378	  assign rsp_q_enq_bits[`WIDBITS+`SHAREMEM_NLANES+`SHAREMEM_NLANES*`XLEN:`SHAREMEM_NLANES*`XLEN] = {core_req_iswrite_st2,core_req_instrid_st2,bankconf_activelane_st2};
379	
380	  stream_fifo_pipe_true_with_count #(
381	    .DATA_WIDTH (1+`WIDBITS+`SHAREMEM_NLANES+`SHAREMEM_NLANES*`XLEN),
382	    .FIFO_DEPTH (RSP_FIFO_DEPTH                                    ),
383	    .CNT_WIDTH  (RSP_FIFO_CNT_DEPTH                                )
384	  )
385	  core_rsp_q (
386	    .clk       (clk             ),
387	    .rst_n     (rst_n           ),
388	    .w_ready_o (rsp_q_enq_ready ),
389	    .w_valid_i (rsp_q_enq_valid ),
390	    .w_data_i  (rsp_q_enq_bits  ),
391	    .r_valid_o (core_rsp_valid_o),
392	    .r_ready_i (core_rsp_ready_i),
393	    .r_data_o  (rsp_q_deq_bits  ),
394	    .count_o   (rsp_q_count     )
395	  );
396	
397	  assign rsp_q_alm_full        = rsp_q_count == (RSP_FIFO_DEPTH - 3)                                ;
398	  assign core_req_ready_o      = !bankconflict_reg && !rsp_q_alm_full && !core_req_isvalid_write_st1;
399	  assign core_rsp_iswrite_o    = rsp_q_deq_bits[`WIDBITS+`SHAREMEM_NLANES+`SHAREMEM_NLANES*`XLEN]   ;
400	  assign core_rsp_instrid_o    = rsp_q_deq_bits[`WIDBITS+`SHAREMEM_NLANES+`SHAREMEM_NLANES*`XLEN-1:`SHAREMEM_NLANES+`SHAREMEM_NLANES*`XLEN];
401	  assign core_rsp_activemask_o = rsp_q_deq_bits[`SHAREMEM_NLANES+`SHAREMEM_NLANES*`XLEN-1:`SHAREMEM_NLANES*`XLEN];
402	  assign core_rsp_data_o       = rsp_q_deq_bits[`SHAREMEM_NLANES*`XLEN-1:0];
403	
404	endmodule
405	
406

