8	 * EITHER EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT,
9	 * MERCHANTABILITY OR FIT FOR A PARTICULAR PURPOSE.
10	 * See the Mulan PSL v2 for more details. */
11	// Author: Tan, Zhiyuan
12	// Description: For dealing with bank conflict: split one require into multiple requre
13	`timescale 1ns/1ns
14	
15	`include "define.v"
16	
17	module bankconflict_arb (
18	  input                                                 clk                           ,
19	  input                                                 rst_n                         ,
20	  input                                                 core_req_arb_is_write_i       ,
21	  input                                                 core_req_arb_enable_i         ,
22	  input  [`SHAREMEM_NLANES-1:0]                         core_req_arb_activemask_i     ,
23	  input  [`SHAREMEM_NLANES*`DCACHE_BLOCKOFFSETBITS-1:0] core_req_arb_blockoffset_i    ,
24	  input  [`SHAREMEM_NLANES*`BYTESOFWORD-1:0]            core_req_arb_wordoffset1h_i   ,
25	  output [`SHAREMEM_NBANKS*`SHAREMEM_NLANES-1:0]        data_crsbar_write_sel1h_o     ,
26	  output [`SHAREMEM_NLANES*`SHAREMEM_NBANKS-1:0]        data_crsbar_read_sel1h_o      ,
27	  output [`SHAREMEM_NBANKS*`SHAREMEM_BANKOFFSET-1:0]    data_crsbar_out_bankoffset_o  ,
28	  output [`SHAREMEM_NBANKS*`BYTESOFWORD-1:0]            data_crsbar_out_wordoffset1h_o,
29	  output [`SHAREMEM_NBANKS-1:0]                         data_array_en_o               ,
30	  output [`SHAREMEM_NLANES-1:0]                         active_lane_o                 ,
31	  output                                                bankconflict_o                
32	);
33	
34	  localparam BANKOFFSET_ISZERO = `DCACHE_BLOCKOFFSETBITS <= `SHAREMEM_BANKIDXBITS;
35	  localparam COUNT_WIDTH       = $clog2(`SHAREMEM_NLANES)                        ;
36	
37	  wire bankconflict             ;
38	  reg  bankconflict_reg         ;
39	  reg  conflict_req_is_write_reg;
40	
41	  wire [`SHAREMEM_NLANES-1:0]      perlane_req_activemask                                  ;
42	  wire [`SHAREMEM_BANKIDXBITS-1:0] perlane_req_bankidx               [0:`SHAREMEM_NLANES-1];
43	  wire [`SHAREMEM_BANKOFFSET-1:0]  perlane_req_bankoffset            [0:`SHAREMEM_NLANES-1];
44	  wire [`BYTESOFWORD-1:0]          perlane_req_wordoffset1h          [0:`SHAREMEM_NLANES-1];
45	  wire [`SHAREMEM_NLANES-1:0]      perlane_conf_req_activemask                             ;
46	  wire [`SHAREMEM_BANKIDXBITS-1:0] perlane_conf_req_bankidx          [0:`SHAREMEM_NLANES-1];
47	  wire [`SHAREMEM_BANKOFFSET-1:0]  perlane_conf_req_bankoffset       [0:`SHAREMEM_NLANES-1];
48	  wire [`BYTESOFWORD-1:0]          perlane_conf_req_wordoffset1h     [0:`SHAREMEM_NLANES-1];
49	  reg  [`SHAREMEM_NLANES-1:0]      perlane_conf_req_activemask_reg                         ;
50	  reg  [`SHAREMEM_BANKIDXBITS*`SHAREMEM_NLANES-1:0] perlane_conf_req_bankidx_reg     ;
51	  reg  [`SHAREMEM_BANKOFFSET*`SHAREMEM_NLANES-1:0]  perlane_conf_req_bankoffset_reg  ;
52	  reg  [`BYTESOFWORD*`SHAREMEM_NLANES-1:0]          perlane_conf_req_wordoffset1h_reg;
53	
54	  genvar i;
55	  generate for(i=0;i<`SHAREMEM_NLANES;i=i+1) begin: INPUT_GEN
56	    assign perlane_req_activemask[i]   = core_req_arb_activemask_i[i] ;
57	    assign perlane_req_bankidx[i]      = core_req_arb_blockoffset_i[i*`DCACHE_BLOCKOFFSETBITS+`SHAREMEM_BANKIDXBITS-1:i*`DCACHE_BLOCKOFFSETBITS];//i*`SHAREDMEM_BLOCKOFFSETBITS];
58	    //assign perlane_req_bankidx[i]      = {1'b0,core_req_arb_blockoffset_i[i]};
59	    assign perlane_req_bankoffset[i]   = BANKOFFSET_ISZERO ? 'd0 : core_req_arb_blockoffset_i[(i+1)*`DCACHE_BLOCKOFFSETBITS-1 -: `SHAREMEM_BANKOFFSET];//i*`SHAREDMEM_BLOCKOFFSETBITS+`SHAREMEM_BANKIDXBITS];
60	    assign perlane_req_wordoffset1h[i] = core_req_arb_wordoffset1h_i[(i+1)*`BYTESOFWORD-1:i*`BYTESOFWORD];
61	  end
62	  endgenerate
63	
64	  wire                             is_write                              ;
65	  wire [`SHAREMEM_BANKIDXBITS-1:0] bank_idx        [0:`SHAREMEM_NLANES-1];
66	  wire [`SHAREMEM_NLANES-1:0]      lane_activemask                       ;
67	  wire [`SHAREMEM_NBANKS-1:0]      bank_idx1h      [0:`SHAREMEM_NLANES-1];
68	  wire [`SHAREMEM_NBANKS-1:0]      bank_idxmasked  [0:`SHAREMEM_NLANES-1];
69	
70	  assign is_write = bankconflict_reg ? conflict_req_is_write_reg : core_req_arb_is_write_i;
71	  
72	  genvar j;
73	  generate for(j=0;j<`SHAREMEM_NLANES;j=j+1) begin: BANK_MASK
74	    assign bank_idx[j]        = perlane_conf_req_bankidx[j]                           ;
75	    assign lane_activemask[j] = perlane_conf_req_activemask[j]                        ;
76	    assign bank_idxmasked[j]  = bank_idx1h[j] & {`SHAREMEM_NBANKS{lane_activemask[j]}};
77	
78	    bin2one #(
79	      .ONE_WIDTH (`SHAREMEM_NBANKS     ),
80	      .BIN_WIDTH (`SHAREMEM_BANKIDXBITS)
81	    )
82	    bankidx_bin2one (
83	      .bin (bank_idx[j]  ),
84	      .oh  (bank_idx1h[j])
85	    );
86	
87	  end
88	  endgenerate
89	
90	  wire [`SHAREMEM_NLANES-1:0] perbank_req_bin                  [0:`SHAREMEM_NBANKS-1];
91	  wire [COUNT_WIDTH-1:0]      perbank_req_count                [0:`SHAREMEM_NBANKS-1];
92	  wire [`SHAREMEM_NBANKS-1:0] perbank_req_conf                                       ;
93	  wire [`SHAREMEM_NLANES-1:0] perbank_activelane_when_conf1h   [0:`SHAREMEM_NBANKS-1];
94	  wire [COUNT_WIDTH-1:0]      perbank_activelane_when_conf_bin [0:`SHAREMEM_NBANKS-1];
95	  wire [`SHAREMEM_NBANKS-1:0] activelane_when_conf             [0:`SHAREMEM_NLANES-1];
96	
97	  genvar n,m;
98	  generate for(n=0;n<`SHAREMEM_NBANKS;n=n+1) begin: COUNT
99	    for(m=0;m<`SHAREMEM_NLANES;m=m+1) begin: CAT
100	      assign perbank_req_bin[n][m]      = bank_idxmasked[m][n]                ;
101	      assign activelane_when_conf[m][n] = perbank_activelane_when_conf1h[n][m];
102	    end
103	    
104	    pop_cnt #(
105	      .DATA_LEN (`SHAREMEM_NLANES),
106	      .DATA_WID (COUNT_WIDTH     )
107	    )
108	    bankreq_count (
109	      .data_i (perbank_req_bin[n]  ),
110	      .data_o (perbank_req_count[n])
111	    );
112	
113	    fixed_pri_arb #(
114	      .ARB_WIDTH (`SHAREMEM_NLANES)
115	    )
116	    conf1h (
117	      .req   (perbank_req_bin[n]               ),
118	      .grant (perbank_activelane_when_conf1h[n])
119	    );
120	
121	    one2bin #(
122	      .ONE_WIDTH (`SHAREMEM_NLANES),
123	      .BIN_WIDTH (COUNT_WIDTH     )
124	    )
125	    conf_bin (
126	      .oh  (perbank_activelane_when_conf1h[n]  ),
127	      .bin (perbank_activelane_when_conf_bin[n])
128	    );
129	
130	    assign perbank_req_conf[n] = (perbank_req_count[n] > 1);
131	  end
132	  endgenerate
133	
134	  assign bankconflict = (|perbank_req_conf) && (core_req_arb_enable_i || bankconflict_reg);
135	
136	  wire [`SHAREMEM_NLANES-1:0] activelane_when_conf1h ;
137	  wire [`SHAREMEM_NLANES-1:0] reservelane_when_conf1h;
138	
139	  genvar k;
140	  generate for(k=0;k<`SHAREMEM_NLANES;k=k+1) begin: ACTIVELANE
141	    assign activelane_when_conf1h[k]  = |activelane_when_conf[k];
142	  end
143	  endgenerate
144	
145	  assign reservelane_when_conf1h = ~activelane_when_conf1h & lane_activemask;
146	
147	  always@(posedge clk or negedge rst_n) begin
148	    if(!rst_n) begin
149	      bankconflict_reg          <= 'd0;
150	      conflict_req_is_write_reg <= 'd0;
151	    end
152	    else begin
153	      bankconflict_reg          <= bankconflict                                                      ;
154	      conflict_req_is_write_reg <= bankconflict ? core_req_arb_is_write_i : conflict_req_is_write_reg;
155	    end
156	  end
157	
158	  genvar x;
159	  generate for(x=0;x<`SHAREMEM_NLANES;x=x+1) begin: PRELANE_REQ_REG
160	    assign perlane_conf_req_activemask[x]   = bankconflict_reg ? perlane_conf_req_activemask_reg[x]                                                     : perlane_req_activemask[x]  ;
161	    assign perlane_conf_req_bankidx[x]      = bankconflict_reg ? perlane_conf_req_bankidx_reg[`SHAREMEM_BANKIDXBITS*(x+1)-1:`SHAREMEM_BANKIDXBITS*x]    : perlane_req_bankidx[x]     ;
162	    assign perlane_conf_req_bankoffset[x]   = bankconflict_reg ? perlane_conf_req_bankoffset_reg[`SHAREMEM_BANKOFFSET*(x+1)-1:`SHAREMEM_BANKOFFSET*x]   : perlane_req_bankoffset[x]  ;
163	    assign perlane_conf_req_wordoffset1h[x] = bankconflict_reg ? perlane_conf_req_wordoffset1h_reg[`BYTESOFWORD*(x+1)-1:`BYTESOFWORD*x]                 : perlane_req_wordoffset1h[x];
164	    
165	    always@(posedge clk or negedge rst_n) begin
166	      if(!rst_n) begin
167	        perlane_conf_req_activemask_reg[x]                                                   <= 'd0;
168	        perlane_conf_req_bankidx_reg[`SHAREMEM_BANKIDXBITS*(x+1)-1:`SHAREMEM_BANKIDXBITS*x]  <= 'd0;
169	        perlane_conf_req_bankoffset_reg[`SHAREMEM_BANKOFFSET*(x+1)-1:`SHAREMEM_BANKOFFSET*x] <= 'd0;
170	        perlane_conf_req_wordoffset1h_reg[`BYTESOFWORD*(x+1)-1:`BYTESOFWORD*x]               <= 'd0;
171	      end
172	      else begin
173	        if(reservelane_when_conf1h[x]) begin
174	          perlane_conf_req_activemask_reg[x]                                                   <= reservelane_when_conf1h[x]      ;
175	          perlane_conf_req_bankidx_reg[`SHAREMEM_BANKIDXBITS*(x+1)-1:`SHAREMEM_BANKIDXBITS*x]  <= perlane_conf_req_bankidx[x]     ;
176	          perlane_conf_req_bankoffset_reg[`SHAREMEM_BANKOFFSET*(x+1)-1:`SHAREMEM_BANKOFFSET*x] <= perlane_conf_req_bankoffset[x]  ;
177	          perlane_conf_req_wordoffset1h_reg[`BYTESOFWORD*(x+1)-1:`BYTESOFWORD*x]               <= perlane_conf_req_wordoffset1h[x];
178	        end
179	        else begin
180	          perlane_conf_req_activemask_reg[x]                                                   <= 1'b0;//perlane_conf_req_activemask_reg[x]  ;
181	          perlane_conf_req_bankidx_reg[`SHAREMEM_BANKIDXBITS*(x+1)-1:`SHAREMEM_BANKIDXBITS*x]  <= perlane_conf_req_bankidx_reg[`SHAREMEM_BANKIDXBITS*(x+1)-1:`SHAREMEM_BANKIDXBITS*x]     ;
182	          perlane_conf_req_bankoffset_reg[`SHAREMEM_BANKOFFSET*(x+1)-1:`SHAREMEM_BANKOFFSET*x] <= perlane_conf_req_bankoffset_reg[`SHAREMEM_BANKOFFSET*(x+1)-1:`SHAREMEM_BANKOFFSET*x]  ;
183	          perlane_conf_req_wordoffset1h_reg[`BYTESOFWORD*(x+1)-1:`BYTESOFWORD*x]               <= perlane_conf_req_wordoffset1h_reg[`BYTESOFWORD*(x+1)-1:`BYTESOFWORD*x];
184	        end
185	      end
186	    end
187	  end
188	  endgenerate
189	
190	  assign active_lane_o  = activelane_when_conf1h;
191	  assign bankconflict_o = bankconflict          ;
192	  
193	  genvar y;
194	  generate for(y=0;y<`SHAREMEM_NBANKS;y=y+1) begin: OUTPUT_WRITE
195	    assign data_crsbar_write_sel1h_o[`SHAREMEM_NLANES*(y+1)-1:`SHAREMEM_NLANES*y]            = perbank_activelane_when_conf1h[y]                                 ;
196	    assign data_crsbar_out_bankoffset_o[`SHAREMEM_BANKOFFSET*(y+1)-1:`SHAREMEM_BANKOFFSET*y] = perlane_conf_req_bankoffset[perbank_activelane_when_conf_bin[y]]  ;
197	    assign data_crsbar_out_wordoffset1h_o[`BYTESOFWORD*(y+1)-1:`BYTESOFWORD*y]               = perlane_conf_req_wordoffset1h[perbank_activelane_when_conf_bin[y]];
198	    assign data_array_en_o[y]                                                                = |perbank_activelane_when_conf1h[y]                                ;
199	  end
200	  endgenerate
201	
202	  genvar z;
203	  generate for(z=0;z<`SHAREMEM_NLANES;z=z+1) begin: OUTPUT_READ
204	    assign data_crsbar_read_sel1h_o[`SHAREMEM_NBANKS*(z+1)-1:`SHAREMEM_NBANKS*z] = bank_idxmasked[z];
205	  end
206	  endgenerate
207	
208	endmodule
209	
210

